import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './CSS/Cart.css';

const Cart = () => {
  // Sample Cart Data State
  const [cartItems, setCartItems] = useState([
    {
      id: 1,
      name: 'Redmi Smartphone',
      category: 'Smartphones',
      price: 14999,
      quantity: 1,
      image: 'https://via.placeholder.com/100'
    },
    {
      id: 2,
      name: 'Wireless Earbuds Pro',
      category: 'Audio',
      price: 2499,
      quantity: 2,
      image: 'https://via.placeholder.com/100'
    }
  ]);

  const [promoCode, setPromoCode] = useState('');
  const [discount, setDiscount] = useState(0);

  // Quantity Handlers
  const handleQuantityChange = (id, delta) => {
    setCartItems(prev =>
      prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          return newQty > 0 ? { ...item, quantity: newQty } : item;
        }
        return item;
      })
    );
  };

  const handleRemoveItem = (id) => {
    setCartItems(prev => prev.filter(item => item.id !== id));
  };

  // Price Calculations
  const subtotal = cartItems.reduce((acc, item) => acc + item.price * item.quantity, 0);
  const shippingFee = subtotal > 0 ? 99 : 0;
  const grandTotal = Math.max(0, subtotal + shippingFee - discount);

  const applyPromo = (e) => {
    e.preventDefault();
    if (promoCode.toUpperCase() === 'HEX10') {
      setDiscount(subtotal * 0.1);
      alert('Promo code applied! 10% discount added.');
    } else {
      alert('Invalid Promo Code. Try "HEX10"');
    }
  };

  return (
    <div className="cart-page-container">
      <div className="cart-header">
        <h1>Your Shopping Cart</h1>
        <p>{cartItems.length} {cartItems.length === 1 ? 'Item' : 'Items'} in cart</p>
      </div>

      {cartItems.length === 0 ? (
        <div className="cart-empty">
          <h2>Your cart is currently empty</h2>
          <p>Explore our products and start shopping!</p>
          <Link to="/products" className="btn-continue">Explore Products</Link>
        </div>
      ) : (
        <div className="cart-content">
          {/* Cart Items List */}
          <div className="cart-items-section">
            <table className="cart-table">
              <thead>
                <tr>
                  <th>Product</th>
                  <th>Price</th>
                  <th>Quantity</th>
                  <th>Total</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {cartItems.map(item => (
                  <tr key={item.id}>
                    <td className="product-info">
                      <img src={item.image} alt={item.name} />
                      <div>
                        <span className="product-title">{item.name}</span>
                        <span className="product-category">{item.category}</span>
                      </div>
                    </td>
                    <td>₹{item.price.toLocaleString()}</td>
                    <td>
                      <div className="qty-controls">
                        <button onClick={() => handleQuantityChange(item.id, -1)}>-</button>
                        <span>{item.quantity}</span>
                        <button onClick={() => handleQuantityChange(item.id, 1)}>+</button>
                      </div>
                    </td>
                    <td>₹{(item.price * item.quantity).toLocaleString()}</td>
                    <td>
                      <button className="btn-remove" onClick={() => handleRemoveItem(item.id)}>
                        ✕
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Order Summary Panel */}
          <div className="cart-summary-section">
            <h3>Order Summary</h3>
            <div className="summary-row">
              <span>Subtotal</span>
              <span>₹{subtotal.toLocaleString()}</span>
            </div>
            <div className="summary-row">
              <span>Shipping Fee</span>
              <span>{shippingFee === 0 ? 'FREE' : `₹${shippingFee}`}</span>
            </div>
            {discount > 0 && (
              <div className="summary-row discount">
                <span>Discount Applied</span>
                <span>-₹{discount.toLocaleString()}</span>
              </div>
            )}
            
            <form onSubmit={applyPromo} className="promo-form">
              <input 
                type="text" 
                placeholder="Promo Code (HEX10)" 
                value={promoCode} 
                onChange={(e) => setPromoCode(e.target.value)} 
              />
              <button type="submit">Apply</button>
            </form>

            <div className="summary-row total">
              <span>Grand Total</span>
              <span>₹{grandTotal.toLocaleString()}</span>
            </div>

            <button className="btn-checkout" onClick={() => alert('Proceeding to Payment!')}>
              Proceed to Checkout
            </button>
            <Link to="/products" className="btn-back">Continue Shopping</Link>
          </div>
        </div>
      )}
    </div>
  );
};

export default Cart;
